-- Clinical Anatomy 3D 1.9.0 - the plug-in's PL/SQL as a package (generated by build.mjs from src/skeleton3d.plsql).
-- Install it once in the application's parsing schema before importing the plug-in, whose callbacks are
-- SKELETON3D_PKG.RENDER / .AJAX / .VALIDATION. Safe to run again.
set define off

create or replace package skeleton3d_pkg as
    function validate_payload(p_value in clob,p_specialty varchar2 default 'ALL',p_sex varchar2 default null) return varchar2;
    function validate_patient(p_value clob,p_context clob,p_options varchar2 default '{}',p_definition clob default null) return varchar2;
    function patient_data(p_source_type in varchar2,p_source in varchar2) return clob;
    procedure render (p_item in apex_plugin.t_item, p_plugin in apex_plugin.t_plugin, p_param in apex_plugin.t_item_render_param, p_result in out nocopy apex_plugin.t_item_render_result);
    procedure ajax (p_item in apex_plugin.t_item, p_plugin in apex_plugin.t_plugin, p_param in apex_plugin.t_item_ajax_param, p_result in out nocopy apex_plugin.t_item_ajax_result);
    procedure validation (p_item in apex_plugin.t_item, p_plugin in apex_plugin.t_plugin, p_param in apex_plugin.t_item_validation_param, p_result in out nocopy apex_plugin.t_item_validation_result);
end skeleton3d_pkg;
/

create or replace package body skeleton3d_pkg as

-- Clinical Anatomy 3D for Oracle APEX - callback package body source.
-- Build generates dist/db/skeleton3d_pkg.sql from this file and payload.plsql.
-- The item value is JSON written by the browser:
--   {"v":1,"sex":"M","sites":[{"area":"KNEE","side":"L","label":"Left knee","pain":6,"note":"...",
--     "diagnoses":[{"code":"M17.9","label":"Gonarthrosis, unspecified","system":"ICD-10"}]}]}
-- Attributes: 1 skeleton (MALE / FEMALE / ITEM), 2 item holding the patient's sex, 3 options, 4 select by,
--   5 height, 6 maximum sites, 7 diagnosis suggestions (enabled/hidden),
--   11 specialty, 12 initial anatomy layer. Retired SQL, clinic-mode and scope attributes are ignored.

c_max_rows constant pls_integer := 60;

-- Shared structural validation for every item mode and application save processes.
function validate_payload(p_value in clob,p_specialty varchar2 default 'ALL',p_sex varchar2 default null) return varchar2 is
    c_area_codes constant varchar2(2000) := 'HEAD:FACE:JAW:NECK:SHOULDER:UPPER_ARM:ELBOW:FOREARM:WRIST:HAND:CHEST:UPPER_BACK:LOWER_BACK:PELVIS:SACRUM:HIP:THIGH:KNEE:LOWER_LEG:ANKLE:FOOT:BRAIN:EAR:EYE:NOSE:THROAT:THYROID:AIRWAY:LUNG:HEART:AORTA:VENA_CAVA:ESOPHAGUS:LIVER:GALLBLADDER:STOMACH:PANCREAS:SPLEEN:SMALL_INTESTINE:COLON:KIDNEY:ADRENAL:URETER:BLADDER:URETHRA:PROSTATE';
    c_anatomy_links constant varchar2(32767) := ':ADRENAL|ADRENAL|L:ADRENAL|ADRENAL|R:AIRWAY|AIRWAY|-:ANTERIOR_CRUCIATE|KNEE|L:ANTERIOR_CRUCIATE|KNEE|R:AORTA|AORTA|-:AORTIC_VALVE|HEART|-:BICEPS|UPPER_ARM|L:BICEPS|UPPER_ARM|R:BLADDER|BLADDER|-:BRACHIAL_ARTERY|UPPER_ARM|L:BRACHIAL_ARTERY|UPPER_ARM|R:BRAIN|BRAIN|-:C1|NECK|-:C2|NECK|-:C3|NECK|-:C4|NECK|-:C5|NECK|-:C6|NECK|-:C7|NECK|-:CALCANEUS|FOOT|L:CALCANEUS|FOOT|R:CAPITATE|WRIST|L:CAPITATE|WRIST|R:CLAVICLE|SHOULDER|L:CLAVICLE|SHOULDER|R:COCCYX|SACRUM|-:COLON|COLON|-:CORNEA|EYE|L:CORNEA|EYE|R:COSTAL_CARTILAGE|CHEST|L:COSTAL_CARTILAGE|CHEST|R:CUBOID|FOOT|L:CUBOID|FOOT|R:CUNEIFORM_INTERMEDIATE|FOOT|L:CUNEIFORM_INTERMEDIATE|FOOT|R:CUNEIFORM_LATERAL|FOOT|L:CUNEIFORM_LATERAL|FOOT|R:CUNEIFORM_MEDIAL|FOOT|L:CUNEIFORM_MEDIAL|FOOT|R:DELTOID|SHOULDER|L:DELTOID|SHOULDER|R:DISC_C2|NECK|-:DISC_C3|NECK|-:DISC_C4|NECK|-:DISC_C5|NECK|-:DISC_C6|NECK|-:DISC_C7|NECK|-:DISC_L1|LOWER_BACK|-:DISC_L2|LOWER_BACK|-:DISC_L3|LOWER_BACK|-:DISC_L4|LOWER_BACK|-:DISC_L5|LOWER_BACK|-:DISC_T10|UPPER_BACK|-:DISC_T11|UPPER_BACK|-:DISC_T12|UPPER_BACK|-:DISC_T1|UPPER_BACK|-:DISC_T2|UPPER_BACK|-:DISC_T3|UPPER_BACK|-:DISC_T4|UPPER_BACK|-:DISC_T5|UPPER_BACK|-:DISC_T6|UPPER_BACK|-:DISC_T7|UPPER_BACK|-:DISC_T8|UPPER_BACK|-:DISC_T9|UPPER_BACK|-:EAR|EAR|L:EAR|EAR|R:ESOPHAGUS|ESOPHAGUS|-:EYE|EYE|L:EYE|EYE|R:FEMORAL_ARTERY|THIGH|L:FEMORAL_ARTERY|THIGH|R:FEMUR|HIP|L:FEMUR|HIP|R:FEMUR|KNEE|L:FEMUR|KNEE|R:FEMUR|THIGH|L:FEMUR|THIGH|R:FIBULA|ANKLE|L:FIBULA|ANKLE|R:FIBULA|KNEE|L:FIBULA|KNEE|R:FIBULA|LOWER_LEG|L:FIBULA|LOWER_LEG|R:FRONTAL|HEAD|-:GALLBLADDER|GALLBLADDER|-:GASTRIC_BODY|STOMACH|-:GASTRIC_CARDIA|STOMACH|-:GASTRIC_FUNDUS|STOMACH|-:GASTRIC_PYLORUS|STOMACH|-:GASTROCNEMIUS|LOWER_LEG|L:GASTROCNEMIUS|LOWER_LEG|R:HAMATE|WRIST|L:HAMATE|WRIST|R:HEART|HEART|-:HUMERUS|ELBOW|L:HUMERUS|ELBOW|R:HUMERUS|SHOULDER|L:HUMERUS|SHOULDER|R:HUMERUS|UPPER_ARM|L:HUMERUS|UPPER_ARM|R:HYOID|NECK|-:ILIUM|PELVIS|L:ILIUM|PELVIS|R:ISCHIUM|PELVIS|L:ISCHIUM|PELVIS|R:KIDNEY|KIDNEY|L:KIDNEY|KIDNEY|R:L1|LOWER_BACK|-:L2|LOWER_BACK|-:L3|LOWER_BACK|-:L4|LOWER_BACK|-:L5|LOWER_BACK|-:LATERAL_MENISCUS|KNEE|L:LATERAL_MENISCUS|KNEE|R:LEFT_ATRIUM|HEART|-:LEFT_VENTRICLE|HEART|-:LENS|EYE|L:LENS|EYE|R:LIVER|LIVER|-:LUNATE|WRIST|L:LUNATE|WRIST|R:LUNG_INFERIOR_LOBE|LUNG|L:LUNG_INFERIOR_LOBE|LUNG|R:LUNG_MIDDLE_LOBE|LUNG|R:LUNG_SUPERIOR_LOBE|LUNG|L:LUNG_SUPERIOR_LOBE|LUNG|R:LUNG|LUNG|L:LUNG|LUNG|R:MANDIBLE|JAW|-:MANUBRIUM|CHEST|-:MAXILLA|FACE|-:MEDIAL_MENISCUS|KNEE|L:MEDIAL_MENISCUS|KNEE|R:MEDIAN_NERVE|FOREARM|L:MEDIAN_NERVE|FOREARM|R:METACARPAL1|HAND|L:METACARPAL1|HAND|R:METACARPAL2|HAND|L:METACARPAL2|HAND|R:METACARPAL3|HAND|L:METACARPAL3|HAND|R:METACARPAL4|HAND|L:METACARPAL4|HAND|R:METACARPAL5|HAND|L:METACARPAL5|HAND|R:METATARSAL1|FOOT|L:METATARSAL1|FOOT|R:METATARSAL2|FOOT|L:METATARSAL2|FOOT|R:METATARSAL3|FOOT|L:METATARSAL3|FOOT|R:METATARSAL4|FOOT|L:METATARSAL4|FOOT|R:METATARSAL5|FOOT|L:METATARSAL5|FOOT|R:MITRAL_VALVE|HEART|-:NASAL|FACE|-:NAVICULAR|FOOT|L:NAVICULAR|FOOT|R:NOSE|NOSE|-:OCCIPITAL|HEAD|-:PANCREAS|PANCREAS|-:PANCREATIC_BODY|PANCREAS|-:PANCREATIC_HEAD|PANCREAS|-:PANCREATIC_TAIL|PANCREAS|-:PARIETAL|HEAD|L:PARIETAL|HEAD|R:PATELLA|KNEE|L:PATELLA|KNEE|R:PECTORALIS|CHEST|L:PECTORALIS|CHEST|R:PHALANX_F1_1|FOOT|L:PHALANX_F1_1|FOOT|R:PHALANX_F1_2|FOOT|L:PHALANX_F1_2|FOOT|R:PHALANX_F2_1|FOOT|L:PHALANX_F2_1|FOOT|R:PHALANX_F2_2|FOOT|L:PHALANX_F2_2|FOOT|R:PHALANX_F2_3|FOOT|L:PHALANX_F2_3|FOOT|R:PHALANX_F3_1|FOOT|L:PHALANX_F3_1|FOOT|R:PHALANX_F3_2|FOOT|L:PHALANX_F3_2|FOOT|R:PHALANX_F3_3|FOOT|L:PHALANX_F3_3|FOOT|R:PHALANX_F4_1|FOOT|L:PHALANX_F4_1|FOOT|R:PHALANX_F4_2|FOOT|L:PHALANX_F4_2|FOOT|R:PHALANX_F4_3|FOOT|L:PHALANX_F4_3|FOOT|R:PHALANX_F5_1|FOOT|L:PHALANX_F5_1|FOOT|R:PHALANX_F5_2|FOOT|L:PHALANX_F5_2|FOOT|R:PHALANX_F5_3|FOOT|L:PHALANX_F5_3|FOOT|R:PHALANX_H1_1|HAND|L:PHALANX_H1_1|HAND|R:PHALANX_H1_2|HAND|L:PHALANX_H1_2|HAND|R:PHALANX_H2_1|HAND|L:PHALANX_H2_1|HAND|R:PHALANX_H2_2|HAND|L:PHALANX_H2_2|HAND|R:PHALANX_H2_3|HAND|L:PHALANX_H2_3|HAND|R:PHALANX_H3_1|HAND|L:PHALANX_H3_1|HAND|R:PHALANX_H3_2|HAND|L:PHALANX_H3_2|HAND|R:PHALANX_H3_3|HAND|L:PHALANX_H3_3|HAND|R:PHALANX_H4_1|HAND|L:PHALANX_H4_1|HAND|R:PHALANX_H4_2|HAND|L:PHALANX_H4_2|HAND|R:PHALANX_H4_3|HAND|L:PHALANX_H4_3|HAND|R:PHALANX_H5_1|HAND|L:PHALANX_H5_1|HAND|R:PHALANX_H5_2|HAND|L:PHALANX_H5_2|HAND|R:PHALANX_H5_3|HAND|L:PHALANX_H5_3|HAND|R:PISIFORM|WRIST|L:PISIFORM|WRIST|R:POSTERIOR_CRUCIATE|KNEE|L:POSTERIOR_CRUCIATE|KNEE|R:PROSTATE|PROSTATE|-:PUBIS|PELVIS|L:PUBIS|PELVIS|R:PULMONARY_VALVE|HEART|-:QUADRICEPS|THIGH|L:QUADRICEPS|THIGH|R:RADIUS|ELBOW|L:RADIUS|ELBOW|R:RADIUS|FOREARM|L:RADIUS|FOREARM|R:RADIUS|WRIST|L:RADIUS|WRIST|R:RENAL_CALYCES|KIDNEY|L:RENAL_CALYCES|KIDNEY|R:RENAL_CORTEX|KIDNEY|L:RENAL_CORTEX|KIDNEY|R:RENAL_MEDULLA|KIDNEY|L:RENAL_MEDULLA|KIDNEY|R:RETINA|EYE|L:RETINA|EYE|R:RIB10|CHEST|L:RIB10|CHEST|R:RIB11|CHEST|L:RIB11|CHEST|R:RIB12|CHEST|L:RIB12|CHEST|R:RIB1|CHEST|L:RIB1|CHEST|R:RIB2|CHEST|L:RIB2|CHEST|R:RIB3|CHEST|L:RIB3|CHEST|R:RIB4|CHEST|L:RIB4|CHEST|R:RIB5|CHEST|L:RIB5|CHEST|R:RIB6|CHEST|L:RIB6|CHEST|R:RIB7|CHEST|L:RIB7|CHEST|R:RIB8|CHEST|L:RIB8|CHEST|R:RIB9|CHEST|L:RIB9|CHEST|R:RIGHT_ATRIUM|HEART|-:RIGHT_VENTRICLE|HEART|-:SACRUM|SACRUM|-:SCAPHOID|WRIST|L:SCAPHOID|WRIST|R:SCAPULA|SHOULDER|L:SCAPULA|SHOULDER|R:SCIATIC_NERVE|THIGH|L:SCIATIC_NERVE|THIGH|R:SMALL_INTESTINE|SMALL_INTESTINE|-:SPHENOID|HEAD|-:SPINAL_CORD|UPPER_BACK|-:SPLEEN|SPLEEN|-:STERNUM|CHEST|-:STOMACH|STOMACH|-:T10|UPPER_BACK|-:T11|UPPER_BACK|-:T12|UPPER_BACK|-:T1|UPPER_BACK|-:T2|UPPER_BACK|-:T3|UPPER_BACK|-:T4|UPPER_BACK|-:T5|UPPER_BACK|-:T6|UPPER_BACK|-:T7|UPPER_BACK|-:T8|UPPER_BACK|-:T9|UPPER_BACK|-:TALUS|ANKLE|L:TALUS|ANKLE|R:TEETH_LOWER|JAW|-:TEETH_UPPER|FACE|-:TEMPORAL|HEAD|L:TEMPORAL|HEAD|R:THROAT|THROAT|-:THYROID|THYROID|-:TIBIA|ANKLE|L:TIBIA|ANKLE|R:TIBIA|KNEE|L:TIBIA|KNEE|R:TIBIA|LOWER_LEG|L:TIBIA|LOWER_LEG|R:TRAPEZIUM|WRIST|L:TRAPEZIUM|WRIST|R:TRAPEZOID|WRIST|L:TRAPEZOID|WRIST|R:TRICUSPID_VALVE|HEART|-:TRIQUETRUM|WRIST|L:TRIQUETRUM|WRIST|R:ULNA|ELBOW|L:ULNA|ELBOW|R:ULNA|FOREARM|L:ULNA|FOREARM|R:ULNA|WRIST|L:ULNA|WRIST|R:URETER|URETER|L:URETER|URETER|R:URETHRA|URETHRA|-:VENA_CAVA|VENA_CAVA|-:XIPHOID|CHEST|-:ZYGOMATIC|FACE|L:ZYGOMATIC|FACE|R:';
    c_specialty_links constant varchar2(32767) := ':ENT|HEAD:ENT|FACE:ENT|JAW:ENT|NECK:ENT|EAR:ENT|NOSE:ENT|THROAT:ENT|THYROID:ENT|AIRWAY:OPHTHALMOLOGY|HEAD:OPHTHALMOLOGY|FACE:OPHTHALMOLOGY|EYE:CARDIOLOGY|CHEST:CARDIOLOGY|HEART:CARDIOLOGY|AORTA:CARDIOLOGY|VENA_CAVA:UROLOGY|PELVIS:UROLOGY|KIDNEY:UROLOGY|ADRENAL:UROLOGY|URETER:UROLOGY|BLADDER:UROLOGY|URETHRA:UROLOGY|PROSTATE:INTERNAL_MEDICINE|CHEST:INTERNAL_MEDICINE|PELVIS:INTERNAL_MEDICINE|THYROID:INTERNAL_MEDICINE|AIRWAY:INTERNAL_MEDICINE|LUNG:INTERNAL_MEDICINE|HEART:INTERNAL_MEDICINE|AORTA:INTERNAL_MEDICINE|VENA_CAVA:INTERNAL_MEDICINE|ESOPHAGUS:INTERNAL_MEDICINE|LIVER:INTERNAL_MEDICINE|GALLBLADDER:INTERNAL_MEDICINE|STOMACH:INTERNAL_MEDICINE|PANCREAS:INTERNAL_MEDICINE|SPLEEN:INTERNAL_MEDICINE|SMALL_INTESTINE:INTERNAL_MEDICINE|COLON:INTERNAL_MEDICINE|KIDNEY:INTERNAL_MEDICINE|ADRENAL:INTERNAL_MEDICINE|URETER:INTERNAL_MEDICINE|BLADDER:INTERNAL_MEDICINE|URETHRA:INTERNAL_MEDICINE|PROSTATE:GASTROENTEROLOGY|ESOPHAGUS:GASTROENTEROLOGY|LIVER:GASTROENTEROLOGY|GALLBLADDER:GASTROENTEROLOGY|STOMACH:GASTROENTEROLOGY|PANCREAS:GASTROENTEROLOGY|SPLEEN:GASTROENTEROLOGY|SMALL_INTESTINE:GASTROENTEROLOGY|COLON:NEUROLOGY|HEAD:NEUROLOGY|FACE:NEUROLOGY|NECK:NEUROLOGY|UPPER_BACK:NEUROLOGY|LOWER_BACK:NEUROLOGY|BRAIN:NEUROLOGY|UPPER_ARM:NEUROLOGY|FOREARM:NEUROLOGY|HAND:NEUROLOGY|THIGH:NEUROLOGY|LOWER_LEG:NEUROLOGY|FOOT:PULMONOLOGY|CHEST:PULMONOLOGY|AIRWAY:PULMONOLOGY|LUNG:ORTHOPEDICS|HEAD:ORTHOPEDICS|FACE:ORTHOPEDICS|JAW:ORTHOPEDICS|NECK:ORTHOPEDICS|SHOULDER:ORTHOPEDICS|UPPER_ARM:ORTHOPEDICS|ELBOW:ORTHOPEDICS|FOREARM:ORTHOPEDICS|WRIST:ORTHOPEDICS|HAND:ORTHOPEDICS|CHEST:ORTHOPEDICS|UPPER_BACK:ORTHOPEDICS|LOWER_BACK:ORTHOPEDICS|PELVIS:ORTHOPEDICS|SACRUM:ORTHOPEDICS|HIP:ORTHOPEDICS|THIGH:ORTHOPEDICS|KNEE:ORTHOPEDICS|LOWER_LEG:ORTHOPEDICS|ANKLE:ORTHOPEDICS|FOOT:';
    type t_keys is table of boolean index by varchar2(1000);
    l_seen t_keys;
    l_term_keys t_keys;
    l_diagnosis_keys t_keys;
    l_marker_keys t_keys;
    l_doc json_object_t;
    l_site json_object_t;
    l_term json_object_t;
    l_marker json_object_t;
    l_exam json_object_t;
    l_answers json_object_t;
    l_answer json_object_t;
    l_context json_object_t;
    l_patient json_object_t;
    l_observation json_object_t;
    l_prefill json_object_t;
    l_observations json_array_t;
    l_details json_array_t;
    l_detail_keys t_keys;
    l_observation_keys t_keys;
    l_names sys.odcivarchar2list;
    l_sites json_array_t;
    l_terms json_array_t;
    l_markers json_array_t;
    l_points json_array_t;
    l_point json_array_t;
    l_element json_element_t;
    l_answer_names json_key_list;
    l_key varchar2(1000);
    l_kind varchar2(20);
    l_number number;

    procedure require(p_ok boolean, p_message varchar2) is
    begin
        if not nvl(p_ok,false) then raise_application_error(-20070,p_message); end if;
    end;

    function present(p_object json_object_t,p_key varchar2) return boolean is
        l_value json_element_t := p_object.get(p_key);
    begin
        return l_value is not null and not l_value.is_null;
    end;

    procedure check_text(p_object json_object_t,p_key varchar2,p_max number) is
        l_value json_element_t := p_object.get(p_key);
    begin
        if l_value is not null and not l_value.is_null then
            require(l_value.is_string,p_key||' must contain text.');
            require(length(p_object.get_string(p_key))<=p_max or p_object.get_string(p_key) is null,p_key||' is too long.');
        end if;
    end;

    function array_value(p_object json_object_t,p_key varchar2) return json_array_t is
        l_value json_element_t := p_object.get(p_key);
    begin
        if l_value is null or l_value.is_null then return json_array_t(); end if;
        require(l_value.is_array,p_key||' must be an array.');
        return treat(l_value as json_array_t);
    end;

    function term_identity(p_term json_object_t,p_default_system varchar2) return varchar2 is
    begin
        if p_term.get_string('source')='CUSTOM' then return 'CUSTOM|'||to_char(p_term.get_number('id'),'TM9'); end if;
        return nvl(p_term.get_string('system'),p_default_system)||'|'||p_term.get_string('code');
    end;
begin
    if p_value is null then return null; end if;
    require(dbms_lob.getlength(p_value)<=1048576,'The anatomy value exceeds 1048576 characters.');
    l_doc := json_object_t.parse(p_value);
    if present(l_doc,'v') then
        l_element:=l_doc.get('v');
        require(l_element.is_number and l_doc.get_number('v') in (1,2),'Unsupported anatomy JSON version.');
    end if;
    if present(l_doc,'contextRefresh') then
        l_context:=l_doc.get_object('contextRefresh');require(l_context is not null,'contextRefresh must be an object.');
        check_text(l_context,'at',100);check_text(l_context,'note',500);check_text(l_context,'previousSex',1);
        require(l_context.get_string('previousSex') in ('M','F','U'),'contextRefresh.previousSex must be M, F or U.');
    end if;
    check_text(l_doc,'sex',1);
    require(p_sex is null or p_sex in ('M','F','U'),'Invalid configured patient sex.');
    require(p_sex is null or not present(l_doc,'sex') or l_doc.get_string('sex')=p_sex,'The model sex does not match the configured patient.');
    require(instr(':ALL:ENT:OPHTHALMOLOGY:CARDIOLOGY:UROLOGY:INTERNAL_MEDICINE:GASTROENTEROLOGY:NEUROLOGY:PULMONOLOGY:ORTHOPEDICS:',':'||p_specialty||':')>0,'Invalid configured specialty.');
    if present(l_doc,'context') then
        l_context:=l_doc.get_object('context'); require(l_context is not null,'context must be an object.');
        require(dbms_lob.getlength(l_context.to_clob)<=32767,'Patient context exceeds 32767 characters.');
        if present(l_context,'patient') then
            l_patient:=l_context.get_object('patient'); require(l_patient is not null,'context.patient must be an object.');
            check_text(l_patient,'name',200); check_text(l_patient,'mrn',200);
            l_names:=sys.odcivarchar2list('id','sex','dateOfBirth','encounterId');
            for n in 1..l_names.count loop check_text(l_patient,l_names(n),100);end loop;
            l_details:=array_value(l_patient,'details');require(l_details.get_size<=12,'Patient details supports up to 12 entries.');
            for j in 0..l_details.get_size-1 loop
                l_observation:=treat(l_details.get(j) as json_object_t);require(l_observation is not null,'Patient details must be objects.');
                check_text(l_observation,'id',64);l_key:=l_observation.get_string('id');
                require(regexp_like(l_key,'^[a-zA-Z][a-zA-Z0-9_]{0,63}$'),'Invalid patient detail ID.');
                require(not l_detail_keys.exists(l_key),'Duplicate patient detail ID.');l_detail_keys(l_key):=true;
                check_text(l_observation,'label',120);check_text(l_observation,'unit',40);
                require(l_observation.has('value'),'Patient detail value is required.');l_element:=l_observation.get('value');
                require(l_element.is_scalar or l_element.is_null,'Patient detail values must be scalar.');
                if l_element.is_string then check_text(l_observation,'value',400);end if;
            end loop;
            if present(l_patient,'age') then
                l_element:=l_patient.get('age'); require(l_element.is_number,'Patient age must be numeric.');
                require(l_patient.get_number('age') between 0 and 150,'Patient age is outside the supported range.');
            end if;
        end if;
        if present(l_context,'recording') then
            l_prefill:=l_context.get_object('recording');require(l_prefill is not null,'recording must be an object.');
            check_text(l_prefill,'source',120);check_text(l_prefill,'recordedBy',120);check_text(l_prefill,'recordedAt',120);
        end if;
        l_observations:=array_value(l_context,'observations'); require(l_observations.get_size<=40,'Context supports up to 40 observations.');
        for j in 0..l_observations.get_size-1 loop
            l_observation:=treat(l_observations.get(j) as json_object_t); require(l_observation is not null,'Observations must be objects.');
            check_text(l_observation,'id',64); l_key:=l_observation.get_string('id');
            require(regexp_like(l_key,'^[a-zA-Z][a-zA-Z0-9_]{0,63}$'),'Invalid observation ID.');
            require(not l_observation_keys.exists(l_key),'Duplicate observation ID.'); l_observation_keys(l_key):=true;
            check_text(l_observation,'label',120); check_text(l_observation,'unit',40); check_text(l_observation,'flag',40);
            check_text(l_observation,'note',500);
            l_names:=sys.odcivarchar2list('source','recordedBy','recordedAt','examField');
            for n in 1..l_names.count loop check_text(l_observation,l_names(n),120); end loop;
            require(l_observation.has('value'),'Observation value is required.');
            l_element:=l_observation.get('value'); require(l_element.is_scalar or l_element.is_null,'Observation values must be scalar.');
            if l_element.is_string then check_text(l_observation,'value',200); end if;
            l_names:=sys.odcivarchar2list('highlight','readOnly','hidden');
            for n in 1..l_names.count loop
                if present(l_observation,l_names(n)) then l_element:=l_observation.get(l_names(n)); require(l_element.is_boolean,l_names(n)||' must be boolean.'); end if;
            end loop;
        end loop;
    end if;
    require(not present(l_doc,'sex') or l_doc.get_string('sex') in ('M','F','U'),'sex must be M, F or U (unconfirmed).');
    require(present(l_doc,'sites'),'sites must be an array.');
    l_sites:=array_value(l_doc,'sites');
    require(l_sites.get_size<=500,'sites supports up to 500 entries.');
    for i in 0..l_sites.get_size-1 loop
        l_site:=treat(l_sites.get(i) as json_object_t);
        require(l_site is not null,'Each site must be an object.');
        check_text(l_site,'area',40);
        require(l_site.get_string('area') is not null and instr(':'||c_area_codes||':',':'||l_site.get_string('area')||':')>0,'Unsupported anatomical area.');
        require(nvl(p_sex,nvl(l_doc.get_string('sex'),'M'))='M' or l_site.get_string('area')<>'PROSTATE','A prostate finding is incompatible with the female model.');
        check_text(l_site,'side',1);
        require(not present(l_site,'side') or l_site.get_string('side') in ('L','R'),'side must be L or R.');
        require(p_specialty='ALL' or instr(c_specialty_links,':'||p_specialty||'|'||l_site.get_string('area')||':')>0,'An anatomical area is outside the configured specialty.');
        l_names:=sys.odcivarchar2list('bone','part');
        for n in 1..l_names.count loop
            check_text(l_site,l_names(n),100);
            if present(l_site,l_names(n)) then
                require(instr(c_anatomy_links,':'||l_site.get_string(l_names(n))||'|'||l_site.get_string('area')||'|'||nvl(l_site.get_string('side'),'-')||':')>0,'The bone or part does not belong to this anatomical area and side.');
            end if;
        end loop;
        require(not present(l_site,'bone') or not present(l_site,'part') or l_site.get_string('bone')=l_site.get_string('part'),'A site cannot identify different bones and parts.');
        l_names:=sys.odcivarchar2list('boneName','partName','label');
        for n in 1..l_names.count loop check_text(l_site,l_names(n),400); end loop;
        check_text(l_site,'note',2000);
        check_text(l_site,'assessment',20);
        require(not present(l_site,'assessment') or l_site.get_string('assessment') in ('NOT_ASSESSED','NORMAL','ABNORMAL'),'Unsupported finding state.');
        if present(l_site,'pain') then
            l_element:=l_site.get('pain');
            require(l_element.is_number,'pain must be numeric.');
            require(l_site.get_number('pain') between 0 and 10,'pain must be between 0 and 10.');
        end if;
        l_key:=case when l_site.get_string('part') is not null then 'P|'||l_site.get_string('part')
                    when l_site.get_string('bone') is not null then 'P|'||l_site.get_string('bone')
                    else 'A|'||l_site.get_string('area') end||'|'||l_site.get_string('side');
        require(not l_seen.exists(l_key),'Duplicate anatomical site.');
        l_seen(l_key):=true;
        l_diagnosis_keys.delete;
        for kind in 1..2 loop
            l_kind:=case kind when 1 then 'diagnoses' else 'complaints' end;
            l_terms:=array_value(l_site,l_kind);
            require(l_terms.get_size<=100,'Each diagnosis or complaint list supports up to 100 entries.');
            l_term_keys.delete;
            for j in 0..l_terms.get_size-1 loop
                l_term:=treat(l_terms.get(j) as json_object_t);
                require(l_term is not null,'Each diagnosis or complaint must be an object.');
                check_text(l_term,'label',400); check_text(l_term,'code',60);
                check_text(l_term,'system',40); check_text(l_term,'source',40); check_text(l_term,'specialty',30);
                require(trim(l_term.get_string('label')) is not null,'A diagnosis or complaint requires a label.');
                if l_term.get_string('source')='CUSTOM' then
                    l_number:=l_term.get_number('id');
                    require(l_number>0 and l_number<=9007199254740991 and trunc(l_number)=l_number,'Custom term ID must be a positive safe integer.');
                else
                    require(trim(l_term.get_string('code')) is not null,'A coded diagnosis or complaint requires a code.');
                end if;
                check_text(l_term,'certainty',20);
                require(not present(l_term,'certainty') or l_term.get_string('certainty') in ('unconfirmed','provisional','differential','confirmed','refuted'),'Unsupported diagnosis certainty.');
                l_key:=term_identity(l_term,case kind when 1 then 'ICD-10' else 'COMPLAINT' end);
                require(not l_term_keys.exists(l_key),'Duplicate diagnosis or complaint.');
                l_term_keys(l_key):=true;
                if kind=1 then l_diagnosis_keys(l_key):=true; end if;
            end loop;
        end loop;
        l_markers:=array_value(l_site,'markers');
        require(l_markers.get_size<=100,'Each site supports up to 100 markers.');
        l_marker_keys.delete;
        for j in 0..l_markers.get_size-1 loop
            l_marker:=treat(l_markers.get(j) as json_object_t);
            require(l_marker is not null,'Each marker must be an object.');
            check_text(l_marker,'kind',5); check_text(l_marker,'id',100); check_text(l_marker,'label',120); check_text(l_marker,'diagnosis',160);
            require(l_marker.get_string('kind') in ('POINT','AREA'),'Marker kind must be POINT or AREA.');
            l_points:=array_value(l_marker,'points');
            require(l_points.get_size between case when l_marker.get_string('kind')='AREA' then 3 else 1 end and 100,'A marker requires valid point coordinates (maximum 100).');
            for k in 0..l_points.get_size-1 loop
                l_point:=treat(l_points.get(k) as json_array_t);
                require(l_point is not null,'Marker coordinates must be arrays.');
                require(l_point.get_size=3,'Marker coordinates require XYZ values.');
                for axis in 0..2 loop l_element:=l_point.get(axis); require(l_element.is_number,'Marker coordinates must be numeric.'); end loop;
            end loop;
            l_key:=l_marker.get_string('id');
            if l_key is not null then require(not l_marker_keys.exists(l_key),'Duplicate marker ID.'); l_marker_keys(l_key):=true; end if;
            l_key:=l_marker.get_string('diagnosis');
            if l_key is not null then require(l_diagnosis_keys.exists(l_key),'A marker must reference a diagnosis at its own site.'); end if;
        end loop;
    end loop;
    if present(l_doc,'exam') then
        l_exam:=l_doc.get_object('exam'); require(l_exam is not null,'exam must be an object.');
        check_text(l_exam,'template',100);check_text(l_exam,'profile',100);
        if present(l_exam,'version') then
            l_element:=l_exam.get('version');l_number:=l_exam.get_number('version');
            require(l_element.is_number and l_number between 0 and 9007199254740991 and trunc(l_number)=l_number,'exam.version must be a nonnegative safe integer.');
        end if;
        if present(l_exam,'answers') then
            l_answers:=l_exam.get_object('answers'); require(l_answers is not null,'exam.answers must be an object.');
            l_answer_names:=l_answers.get_keys;
            require(l_answer_names.count<=100,'exam.answers supports up to 100 entries.');
            for i in 1..l_answer_names.count loop
                require(regexp_like(l_answer_names(i),'^[a-zA-Z][a-zA-Z0-9_]{0,127}$'),'Invalid examination field ID.');
                l_answer:=l_answers.get_object(l_answer_names(i)); require(l_answer is not null,'Each examination answer must be an object.');
                check_text(l_answer,'note',500);
                if present(l_answer,'prefill') then
                    l_prefill:=l_answer.get_object('prefill'); require(l_prefill is not null,'prefill must be an object.');
                    check_text(l_prefill,'source',120); check_text(l_prefill,'recordedBy',120); check_text(l_prefill,'recordedAt',120);
                    if present(l_prefill,'locked') then l_element:=l_prefill.get('locked'); require(l_element.is_boolean,'prefill.locked must be boolean.'); end if;
                end if;
                if present(l_answer,'value') then
                    l_element:=l_answer.get('value'); require(l_element.is_scalar,'Examination values must be scalar.');
                    if l_element.is_string then check_text(l_answer,'value',2000); end if;
                end if;
                if present(l_answer,'deferred') then
                    l_element:=l_answer.get('deferred'); require(l_element.is_boolean,'deferred must be boolean.');
                end if;
            end loop;
        end if;
    end if;
    return null;
exception when others then
    if sqlcode=-20070 then return substr(sqlerrm,12); end if;
    return 'The anatomy JSON could not be read. Check the document and its field types.';
end validate_payload;

-- Canonicalize the server source in the same way as patient-contract.js.
function normalized_context(p_value clob) return json_object_t is
    l_source json_object_t;
    l_result json_object_t:=json_object_t();
    l_patient json_object_t:=json_object_t();
    l_recording json_object_t;
    l_rows json_array_t;
    l_out json_array_t:=json_array_t();
    l_row json_object_t;
    l_clean json_object_t;
    l_preset json_object_t;
    l_presets json_object_t:=json_object_t.parse(q'~{"bp_systolic":{"label":"Systolic BP","unit":"mmHg"},"bp_diastolic":{"label":"Diastolic BP","unit":"mmHg"},"pulse":{"label":"Pulse","unit":"beats/min"},"respiratory_rate":{"label":"Respiratory rate","unit":"breaths/min"},"temperature":{"label":"Temperature","unit":"\u00b0C"},"spo2":{"label":"Oxygen saturation","unit":"%"},"weight":{"label":"Weight","unit":"kg"},"height":{"label":"Height","unit":"cm"},"bmi":{"label":"BMI","unit":"kg/m\u00b2"},"glucose":{"label":"Blood glucose","unit":"mmol/L"},"pain":{"label":"Pain score","unit":"/10"}}~');
    l_value json_element_t;
    l_keys sys.odcivarchar2list;
    procedure copy_fields(p_from json_object_t,p_to in out nocopy json_object_t,p_keys sys.odcivarchar2list) is
        l_value json_element_t;
    begin
        if p_from is null then return; end if;
        for i in 1..p_keys.count loop
            l_value:=p_from.get(p_keys(i));
            if l_value is not null and not l_value.is_null then p_to.put(p_keys(i),l_value); end if;
        end loop;
    end;
begin
    if p_value is null then return null; end if;
    l_source:=json_object_t.parse(p_value);
    copy_fields(l_source.get_object('patient'),l_patient,sys.odcivarchar2list('name','mrn','id','sex','dateOfBirth','encounterId','age'));
    if l_source.get_object('patient') is not null then
        l_patient:=l_source.get_object('patient');
        l_rows:=l_patient.get_array('details');
        l_patient:=json_object_t();
        copy_fields(l_source.get_object('patient'),l_patient,sys.odcivarchar2list('name','mrn','id','sex','dateOfBirth','encounterId','age'));
        if l_rows is not null then
            for i in 0..l_rows.get_size-1 loop
                l_row:=treat(l_rows.get(i) as json_object_t);l_clean:=json_object_t();
                copy_fields(l_row,l_clean,sys.odcivarchar2list('id','unit'));l_clean.put('value',l_row.get('value'));
                l_clean.put('label',nvl(l_row.get_string('label'),l_row.get_string('id')));l_out.append(l_clean);
            end loop;
            l_patient.put('details',l_out);
        end if;
    end if;
    l_result.put('patient',l_patient);
    if l_source.get_object('recording') is not null then
        l_recording:=json_object_t();
        copy_fields(l_source.get_object('recording'),l_recording,sys.odcivarchar2list('source','recordedBy','recordedAt'));
        l_result.put('recording',l_recording);
    end if;
    l_rows:=l_source.get_array('observations');l_out:=json_array_t();
    if l_rows is not null then
        for i in 0..l_rows.get_size-1 loop
            l_row:=treat(l_rows.get(i) as json_object_t);l_clean:=json_object_t();
            copy_fields(l_row,l_clean,sys.odcivarchar2list('id','unit','flag','source','recordedBy','recordedAt','examField','note','highlight','readOnly','hidden'));
            l_clean.put('value',l_row.get('value'));l_preset:=l_presets.get_object(l_row.get_string('id'));
            l_clean.put('label',nvl(l_row.get_string('label'),case when l_preset is not null then nvl(l_preset.get_string('label'),l_row.get_string('id')) else l_row.get_string('id') end));
            l_value:=l_row.get('unit');
            if (l_value is null or l_value.is_null) and l_preset is not null and l_preset.has('unit') then l_clean.put('unit',l_preset.get('unit')); end if;
            l_out.append(l_clean);
        end loop;
    end if;
    l_result.put('observations',l_out);return l_result;
end;

-- p_context and p_definition MUST come from authorized server queries, never request JSON.
function validate_patient(p_value clob,p_context clob,p_options varchar2 default '{}',p_definition clob default null) return varchar2 is
    l_doc json_object_t;
    l_expected json_object_t;
    l_actual json_object_t;
    l_options json_object_t;
    l_exam json_object_t;
    l_answers json_object_t:=json_object_t();
    l_answer json_object_t;
    l_prefill json_object_t;
    l_expected_prefill json_object_t;
    l_recording json_object_t;
    l_rows json_array_t;
    l_row json_object_t;
    l_fields json_array_t;
    l_field json_object_t;
    l_value json_element_t;
    l_choices json_array_t;
    l_choice json_object_t;
    l_notes json_array_t;
    l_names json_key_list;
    l_keys sys.odcivarchar2list:=sys.odcivarchar2list('source','recordedBy','recordedAt');
    l_field_id varchar2(128);
    l_patient json_object_t;
    l_sex varchar2(100);
    l_error varchar2(4000);
    l_text varchar2(120);
    l_locked boolean;
    l_known boolean;
    l_match number;
    l_left clob;
    l_right clob;
    function same(p_left json_element_t,p_right json_element_t) return boolean is
    begin
        if p_left is null or p_right is null then return p_left is null and p_right is null; end if;
        l_left:=p_left.to_clob;l_right:=p_right.to_clob;
        select case when json_equal(l_left,l_right) then 1 else 0 end into l_match from dual;
        return l_match=1;
    end;
begin
    begin
        l_options:=json_object_t.parse(nvl(p_options,'{}'));
        if l_options is null then raise_application_error(-20071,'Options must be an object.');end if;
    exception when others then return 'Display & Prefill Options must be a valid JSON object. Leave {} for defaults.'; end;
    if p_value is null then return null; end if;
    if p_context is not null then
        l_error:=validate_payload(to_clob('{"sites":[],"context":')||p_context||'}');
        if l_error is not null then return 'The authorized patient source is invalid: '||l_error; end if;
    end if;
    l_doc:=json_object_t.parse(p_value);l_expected:=normalized_context(p_context);
    l_actual:=l_doc.get_object('context');l_exam:=l_doc.get_object('exam');
    if l_exam is not null and l_exam.get_object('answers') is not null then l_answers:=l_exam.get_object('answers'); end if;
    if l_actual is not null and (l_expected is null or not same(l_actual,l_expected)) then
        return 'The patient snapshot differs from the authorized server source. Reload the patient data before saving.';
    end if;
    l_names:=l_answers.get_keys;
    if l_expected is null then
        for i in 1..l_names.count loop
            l_answer:=l_answers.get_object(l_names(i));
            if l_answer.get_object('prefill') is not null then return 'Prefill history requires an authorized JSON, SQL or PL/SQL patient source.'; end if;
        end loop;
        return null;
    end if;
    l_patient:=l_expected.get_object('patient');
    if l_patient.has('sex') then
        l_sex:=upper(trim(l_patient.get_string('sex')));
        l_sex:=case when l_sex in ('M','MALE') then 'M' when l_sex in ('F','FEMALE') then 'F' else 'U' end;
        l_error:=validate_payload(p_value,'ALL',l_sex);
        if l_error is not null then return l_error; end if;
    end if;
    if nvl(l_options.get_boolean('saveContext'),false) and l_actual is null then return 'The patient snapshot is missing. Reload the patient data before saving.'; end if;
    if p_definition is not null then l_field:=json_object_t.parse(p_definition);l_fields:=l_field.get_array('fields'); end if;
    l_rows:=l_expected.get_array('observations');l_recording:=l_expected.get_object('recording');
    if l_recording is null then l_recording:=json_object_t(); end if;
    -- Reject invented provenance even on an otherwise unlocked answer.
    for i in 1..l_names.count loop
        l_answer:=l_answers.get_object(l_names(i));
        if l_answer.get_object('prefill') is not null then
            l_known:=false;
            for j in 0..l_rows.get_size-1 loop
                l_row:=treat(l_rows.get(j) as json_object_t);
                if nvl(l_row.get_string('examField'),l_row.get_string('id'))=l_names(i) then l_known:=true; end if;
            end loop;
            if not l_known then return 'An examination answer contains unverified prefill history.'; end if;
        end if;
    end loop;
    for j in 0..l_rows.get_size-1 loop
        l_row:=treat(l_rows.get(j) as json_object_t);l_field_id:=nvl(l_row.get_string('examField'),l_row.get_string('id'));
        l_answer:=l_answers.get_object(l_field_id);l_known:=false;
        l_value:=l_row.get('value');
        if l_fields is not null then
            for i in 0..l_fields.get_size-1 loop
                l_field:=treat(l_fields.get(i) as json_object_t);
                if l_field.get_string('id')=l_field_id and (l_row.get_string('unit') is null or l_field.get_string('unit') is null or l_row.get_string('unit')=l_field.get_string('unit')) then
                    l_known:=l_value is not null and not l_value.is_null and (l_value.is_number or l_value.is_boolean or l_row.get_string('value') is not null);
                    if l_field.get_string('type')='number' then
                        l_known:=l_known and l_value.is_number and (not l_field.has('min') or l_row.get_number('value')>=l_field.get_number('min')) and (not l_field.has('max') or l_row.get_number('value')<=l_field.get_number('max'));
                    elsif l_field.get_string('type')='checkbox' then l_known:=l_known and l_value.is_boolean;
                    elsif l_field.get_string('type')='assessment' then l_known:=l_known and l_row.get_string('value') in ('NORMAL','ABNORMAL');
                    elsif l_field.get_string('type')='select' then
                        l_known:=false;l_choices:=l_field.get_array('options');
                        for n in 0..l_choices.get_size-1 loop l_choice:=treat(l_choices.get(n) as json_object_t);if l_choice.get_string('value')=l_row.get_string('value') then l_known:=true;end if;end loop;
                    end if;
                    l_notes:=l_field.get_array('noteRequiredFor');
                    if l_notes is not null then for n in 0..l_notes.get_size-1 loop if l_notes.get_string(n)=l_row.get_string('value') then l_known:=false;end if;end loop;end if;
                    exit;
                end if;
            end loop;
        end if;
        l_locked:=nvl(l_row.get_boolean('readOnly'),false) or nvl(l_options.get_boolean('lockPrefilled'),false);
        if (l_known and l_locked and nvl(l_options.get_boolean('prefillExam'),true))
           or (l_answer is not null and l_answer.get_object('prefill') is not null) then
            if l_answer is null then return 'A locked prefilled examination answer is missing.'; end if;
            l_prefill:=l_answer.get_object('prefill');l_expected_prefill:=json_object_t();
            for i in 1..l_keys.count loop
                l_text:=nvl(l_row.get_string(l_keys(i)),l_recording.get_string(l_keys(i)));
                if i=1 then l_text:=nvl(l_text,'Supplied observation'); end if;
                if l_text is not null then l_expected_prefill.put(l_keys(i),l_text); end if;
            end loop;
            l_expected_prefill.put('locked',l_locked);
            if l_prefill is null or not same(l_prefill,l_expected_prefill) or not same(l_answer.get('value'),l_row.get('value'))
               or nvl(l_answer.get_boolean('deferred'),false) then
                return 'A prefilled value or its source history changed. Reload the patient data before saving.';
            end if;
        end if;
    end loop;
    return null;
exception when others then
    apex_debug.error('Clinical Anatomy 3D patient validation: %s',sqlerrm);
    return 'The patient source could not be verified. Reload the patient data before saving.';
end;


function attr ( p_item in apex_plugin.t_item, p_no in pls_integer ) return varchar2
is
begin
    return p_item.attributes.get_varchar2('attribute_' || to_char(p_no, 'FM00'));
exception
    when others then
        return null;
end attr;

-- Trusted developer-configured sources only. Browser requests never supply SQL or PL/SQL.
function patient_data(p_source_type in varchar2,p_source in varchar2) return clob is
    l_ctx apex_exec.t_context;
    l_column apex_exec.t_column;
    l_open boolean:=false;
    l_value clob;
    l_error varchar2(4000);
    l_object json_object_t;
begin
    if p_source is null then return null; end if;
    case p_source_type
    when 'ITEM' then l_value:=to_clob(v(p_source));
    when 'JSON' then l_value:=to_clob(p_source);
    when 'PLSQL' then l_value:=apex_plugin_util.get_plsql_func_result_clob(p_plsql_function=>p_source);
    when 'SQL' then
        l_ctx:=apex_exec.open_query_context(p_location=>apex_exec.c_location_local_db,p_sql_query=>rtrim(trim(p_source),';'),p_max_rows=>2,p_auto_bind_items=>true);
        l_open:=true;
        if apex_exec.get_column_count(l_ctx)<>1 then raise_application_error(-20071,'Patient query must return exactly one JSON column.');end if;
        if apex_exec.next_row(l_ctx) then
            l_column:=apex_exec.get_column(l_ctx,1);
            if l_column.data_type=apex_exec.c_data_type_clob then l_value:=apex_exec.get_clob(l_ctx,1);
            else l_value:=to_clob(apex_exec.get_varchar2(l_ctx,1));end if;
            if apex_exec.next_row(l_ctx) then raise_application_error(-20071,'Patient query must return at most one row.');end if;
        end if;
        apex_exec.close(l_ctx);l_open:=false;
    else return null;
    end case;
    if l_value is not null then
        l_object:=json_object_t.parse(l_value);
        l_error:=validate_payload(to_clob('{"v":2,"sites":[],"context":')||l_value||'}');
        if l_error is not null then raise_application_error(-20071,l_error);end if;
    end if;
    return l_value;
exception when others then
    if l_open then apex_exec.close(l_ctx);end if;
    raise;
end patient_data;

-- Optional host authorization runs before rendering, refreshing or validating any source.
function item_patient_data(p_item apex_plugin.t_item) return clob is
    l_type varchar2(20):=nvl(attr(p_item,26),'ITEM');
    l_condition varchar2(32767):=attr(p_item,31);
    l_result clob;
    l_doc json_object_t;
    l_patient json_object_t;
begin
    if l_type not in ('NONE','ITEM','JSON','SQL','PLSQL') then raise_application_error(-20071,'Choose a supported Patient Data Source.');end if;
    if l_condition is not null and not nvl(apex_plugin_util.get_plsql_func_result_boolean(p_plsql_function=>l_condition),false) then
        raise_application_error(-20071,'Patient access is not authorized.');
    end if;
    l_result:=patient_data(l_type,case l_type when 'ITEM' then attr(p_item,23) when 'JSON' then attr(p_item,27) when 'SQL' then attr(p_item,28) when 'PLSQL' then attr(p_item,29) end);
    if l_type='ITEM' and (attr(p_item,21) is not null or attr(p_item,22) is not null) then
        l_doc:=case when l_result is null then json_object_t() else json_object_t.parse(l_result) end;
        l_patient:=l_doc.get_object('patient');if l_patient is null then l_patient:=json_object_t();end if;
        if not l_patient.has('name') and attr(p_item,21) is not null and v(attr(p_item,21)) is not null then l_patient.put('name',substr(v(attr(p_item,21)),1,200));end if;
        if not l_patient.has('mrn') and attr(p_item,22) is not null and v(attr(p_item,22)) is not null then l_patient.put('mrn',substr(v(attr(p_item,22)),1,200));end if;
        l_doc.put('patient',l_patient);l_result:=l_doc.to_clob;
    end if;
    return l_result;
end;

function to_int ( p_val in varchar2, p_default in number ) return number
is
begin
    return nvl(to_number(regexp_substr(p_val, '\d{1,6}')), p_default);
exception
    when others then
        return p_default;
end to_int;

function has ( p_list in varchar2, p_value in varchar2 ) return boolean
is
begin
    return instr(':' || p_list || ':', ':' || p_value || ':') > 0;
end has;

-- Shared dictionaries and exam definitions are maintained by explicitly authorized users.
function clinic_maintainer(p_item in apex_plugin.t_item) return boolean is
    l_condition varchar2(32767):=attr(p_item,19);
begin
    if apex_application.g_user is null or upper(apex_application.g_user) in ('NOBODY','APEX_PUBLIC_USER','HTMLDB_PUBLIC_USER') then return false; end if;
    if trim(l_condition) is null then return false; end if;
    return nvl(apex_plugin_util.get_plsql_func_result_boolean(p_plsql_function=>l_condition),false);
exception when others then
    apex_debug.error('Clinical Anatomy 3D maintainer authorization failed for %s: %s',p_item.name,sqlerrm);
    return false;
end;

function clinic_permissions(p_item in apex_plugin.t_item,p_maintainer boolean) return varchar2 is
begin
    if p_maintainer then return nvl(attr(p_item,15),'NONE'); end if;
    return 'NONE';
end;

function clinic_write_token(p_item in apex_plugin.t_item) return varchar2 is
begin
    return apex_util.get_hash(apex_t_varchar2('SKELETON3D_CLINIC',to_char(apex_application.g_flow_id),to_char(apex_application.g_flow_step_id),p_item.name));
end;

-- M or F from the attribute, or from the page item with the patient's sex (M, F, Male, Female ...)
function sex ( p_item in apex_plugin.t_item,p_context clob default null ) return varchar2
is
    l_kind varchar2(30) := nvl(attr(p_item, 1), 'MALE');
    l_val  varchar2(255);
    l_doc json_object_t;
begin
    if p_context is not null then
        l_doc:=json_object_t.parse(p_context);l_doc:=l_doc.get_object('patient');
        if l_doc is not null and l_doc.has('sex') then
            l_val:=upper(trim(l_doc.get_string('sex')));
            return case when l_val in ('F','FEMALE') then 'F' when l_val in ('M','MALE') then 'M' else 'U' end;
        end if;
    end if;
    if l_kind = 'ITEM' and attr(p_item, 2) is not null then
        l_val := upper(trim(v(attr(p_item, 2))));
        return case when l_val in ('F','FEMALE') then 'F' when l_val in ('M','MALE') then 'M' else 'U' end;
    end if;
    return case when l_kind = 'FEMALE' then 'F' when l_kind='MALE' then 'M' else 'U' end;
end sex;

function specialty(p_item in apex_plugin.t_item) return varchar2 is
    l_value varchar2(100);
begin
    l_value:=upper(trim(case when attr(p_item,20) is not null then v(attr(p_item,20)) else attr(p_item,11) end));
    if l_value in ('ALL','ENT','OPHTHALMOLOGY','CARDIOLOGY','UROLOGY','INTERNAL_MEDICINE','GASTROENTEROLOGY','NEUROLOGY','PULMONOLOGY','ORTHOPEDICS') then return l_value; end if;
    return 'ALL';
end;

----------------------------------------------------------------------------
-- render
----------------------------------------------------------------------------
procedure render (
    p_item   in            apex_plugin.t_item,
    p_plugin in            apex_plugin.t_plugin,
    p_param  in            apex_plugin.t_item_render_param,
    p_result in out nocopy apex_plugin.t_item_render_result )
is
    l_name varchar2(255) := p_item.name;
    l_maintainer boolean := clinic_maintainer(p_item);
    l_permissions varchar2(100) := clinic_permissions(p_item,l_maintainer);
    l_ro   boolean := nvl(p_param.is_readonly,false) or nvl(p_param.is_printer_friendly,false);
    l_opt  varchar2(4000) := attr(p_item, 3);
    l_src  varchar2(30) := case when attr(p_item,7)='NONE' then 'NONE' else 'BUILTIN' end;
    l_json clob;
    l_submit varchar2(32767);
    l_patient clob;
    l_patient_error varchar2(4000);
    l_patient_type varchar2(20):=nvl(attr(p_item,26),'ITEM');
    l_value clob := coalesce(p_param.session_state_value.clob_value,to_clob(p_param.session_state_value.varchar2_value),to_clob(p_param.value));
begin
    begin
        l_patient:=item_patient_data(p_item);
    exception when others then
        apex_debug.error('Anatomy patient source %s: %s',p_item.name,sqlerrm);
        l_patient_error:='Patient data could not be loaded. Retry or contact the application administrator.';
    end;
    apex_json.initialize_clob_output;
    apex_json.open_object;
    apex_json.write('sex', sex(p_item,l_patient));
    apex_json.write('theme',lower(nvl(attr(p_item,32),'apex')));
    apex_json.write('colorMode',nvl(attr(p_item,33),'CLINICAL'));
    apex_json.write('neonColor',nvl(attr(p_item,34),'#36f5ff'));
    apex_json.write('sexSwitch', false);
    apex_json.write('sexLocked', not l_ro);
    apex_json.write('specialty', specialty(p_item));
    apex_json.write('specialtyItem',attr(p_item,20));
    apex_json.write('patientNameItem',attr(p_item,21));
    apex_json.write('patientMrnItem',attr(p_item,22));
    apex_json.write('contextSourceItem',attr(p_item,23));
    apex_json.write('contextSourceType',l_patient_type);
    apex_json.write('contextData',l_patient);
    apex_json.write('contextSourceError',l_patient_error);
    l_submit:=trim(both ',' from replace(attr(p_item,30)||case when l_patient_type='ITEM' then ','||attr(p_item,23)||','||attr(p_item,21)||','||attr(p_item,22) end,' '));
    if l_submit is not null then apex_json.write('contextItemsToSubmit','#'||regexp_replace(l_submit,'[,:]+',',#'));end if;
    apex_json.write('contextOptions',nvl(attr(p_item,24),'{}'));
    apex_json.write('selectionGesture',nvl(attr(p_item,25),'SINGLE'));
    apex_json.write('specialtySwitch', has(l_opt, 'SPECIALTY_SWITCH') and specialty(p_item)='ALL');
    apex_json.write('layer', nvl(attr(p_item, 12), 'AUTO'));
    apex_json.write('clinicPermissions', case when l_ro then 'NONE' else l_permissions end);
    apex_json.write('examMode', nvl(attr(p_item, 16), 'OFF'));
    apex_json.write('modelTools', attr(p_item, 17));
    if not l_ro and l_maintainer then apex_json.write('clinicToken',clinic_write_token(p_item)); end if;
    apex_json.write('selectBy', nvl(attr(p_item, 4), 'AREA'));
    apex_json.write('selectBySwitch', has(l_opt, 'MODE_SWITCH'));
    apex_json.write('complaints', has(l_opt, 'COMPLAINTS'));
    apex_json.write('search', has(l_opt, 'SEARCH'));
    apex_json.write('pain', has(l_opt, 'PAIN'));
    apex_json.write('note', has(l_opt, 'NOTE'));
    apex_json.write('height', greatest(320, least(to_int(attr(p_item, 5), 560), 1200)));
    apex_json.write('maxSites', to_int(attr(p_item, 6), 0));
    apex_json.write('dxSource', l_src);
    apex_json.write('readOnly', l_ro);
    apex_json.write('ajaxId', apex_plugin.get_ajax_identifier);
    apex_json.close_object;
    l_json := apex_json.get_clob_output;
    apex_json.free_output;

    sys.htp.prn('<textarea hidden id="' || l_name || '"' || case when not l_ro then ' name="' || l_name || '"' end || '>');
    apex_util.prn(apex_escape.html_clob(l_value),false);
    sys.htp.p('</textarea><div id="' || l_name || '_SK3" class="sk3" role="group" aria-label="' || apex_escape.html_attribute(p_item.plain_label) || '"></div>');
    sys.htp.prn('<script type="application/json" id="' || l_name || '_SK3_CFG">');
    apex_util.prn(replace(l_json, '<', '\u003c'), false);
    sys.htp.p('</script>');

    apex_javascript.add_onload_code(
        'skeleton3d.init("' || l_name || '", JSON.parse(document.getElementById("' || l_name || '_SK3_CFG").textContent)'
        || case when p_item.init_javascript_code is not null then ', ' || p_item.init_javascript_code end || ');');

    p_result.is_navigable     := not l_ro;
    p_result.navigable_dom_id := l_name || '_SK3';
end render;

----------------------------------------------------------------------------
-- ajax: diagnoses of the application's own list, for the areas in x02 and / or the words in x03.
-- Diagnosis Query columns by position: code, title, areas (optional, e.g. KNEE:HIP), coding system (optional)
----------------------------------------------------------------------------
procedure ajax (
    p_item in apex_plugin.t_item,p_plugin in apex_plugin.t_plugin,
    p_param in apex_plugin.t_item_ajax_param,p_result in out nocopy apex_plugin.t_item_ajax_result)
is
    l_maintainer boolean:=clinic_maintainer(p_item);
    l_permissions varchar2(100):=clinic_permissions(p_item,l_maintainer);
    procedure json_header is
    begin
        sys.owa_util.mime_header('application/json; charset=utf-8',false);
        sys.htp.p('Cache-Control: no-store');sys.owa_util.http_header_close;
    end;
begin
    if apex_application.g_x01='PATIENT_CONTEXT' then
        json_header;
        apex_json.initialize_clob_output;apex_json.open_object;
        begin apex_json.write('contextData',item_patient_data(p_item));
        exception when others then
            apex_debug.error('Anatomy patient refresh %s: %s',p_item.name,sqlerrm);
            apex_json.write('error','Patient data could not be loaded. Retry or contact the application administrator.');
        end;
        apex_json.close_object;apex_util.prn(apex_json.get_clob_output,false);apex_json.free_output;return;
    end if;
    if apex_application.g_x01 like 'CLINIC\_%' escape '\' then
        apex_json.initialize_output(p_http_header=>false);
        if apex_application.g_x01 in ('CLINIC_CREATE','CLINIC_CONFIGURE') and
           (not l_maintainer or apex_application.g_x09 is null or apex_application.g_x09<>clinic_write_token(p_item)) then
            json_header;apex_json.open_object;apex_json.write('error','The clinic operation is unavailable for this item.');apex_json.close_object;return;
        end if;
        begin
            execute immediate 'begin ca3d_clinic_api.ajax(:action,:permissions,:exam_mode); end;'
                using apex_application.g_x01,l_permissions,nvl(attr(p_item,16),'OFF');
        exception when others then
            apex_debug.error('Clinical Anatomy 3D clinic service %s: %s',p_item.name,sqlerrm);
            json_header;apex_json.initialize_output(p_http_header=>false);apex_json.open_object;
            apex_json.write('error',case when apex_application.g_x01='CLINIC_LOAD' then 'The examination service is unavailable. Retry or ask the administrator to install or compile CA3D_CLINIC_API.' else 'The shared catalogue service is unavailable. Retry or contact the application administrator.' end);
            apex_json.close_object;
        end;
        return;
    end if;
    json_header;apex_json.initialize_output(p_http_header=>false);apex_json.open_object;
    apex_json.write('error','Unsupported anatomy request. Diagnoses and complaints use the shared catalogue.');apex_json.close_object;
end ajax;

----------------------------------------------------------------------------
-- validation: the value must be the JSON this item writes, within the Maximum Sites
----------------------------------------------------------------------------
procedure validation (
    p_item   in            apex_plugin.t_item,
    p_plugin in            apex_plugin.t_plugin,
    p_param  in            apex_plugin.t_item_validation_param,
    p_result in out nocopy apex_plugin.t_item_validation_result )
is
    l_max   pls_integer := to_int(attr(p_item, 6), 0);
    l_doc   sys.json_object_t;
    l_sites sys.json_array_t;
    l_value clob := coalesce(p_param.session_state_value.clob_value,to_clob(p_param.session_state_value.varchar2_value),to_clob(p_param.value));
    l_clinic_error varchar2(4000);
    l_has_custom pls_integer;
    l_patient clob;
    l_definition clob;
    l_patient_type varchar2(20):=nvl(attr(p_item,26),'ITEM');
    l_patient_options json_object_t;
    l_patient_doc json_object_t;
    l_patient_sex varchar2(100);
    l_expected_sex varchar2(1):=sex(p_item);
    l_maintainer boolean := clinic_maintainer(p_item);
    l_permissions varchar2(100) := clinic_permissions(p_item,l_maintainer);
begin
    l_clinic_error:=validate_payload(l_value,specialty(p_item));
    if l_clinic_error is not null then p_result.message:=l_clinic_error; return; end if;
    select case when json_exists(l_value,'$.sites[*].diagnoses[*]?(@.source == "CUSTOM")')
                     or json_exists(l_value,'$.sites[*].complaints[*]?(@.source == "CUSTOM")') then 1 else 0 end
      into l_has_custom from dual;
    if l_has_custom=1 or json_exists(l_value,'$.exam') or nvl(attr(p_item,16),'OFF')<>'OFF' then
        begin
            execute immediate 'begin :message:=ca3d_clinic_api.validate_value(:value,:exam_mode); end;'
                using out l_clinic_error,in l_value,in nvl(attr(p_item,16),'OFF');
        exception when others then
            apex_debug.error('Clinical Anatomy 3D clinic validation %s: %s',p_item.name,sqlerrm);
            p_result.message:='The examination and clinic validation service is unavailable. Contact the application administrator to install or compile CA3D_CLINIC_API.';
            return;
        end;
        if l_clinic_error is not null then p_result.message:=l_clinic_error; return; end if;
    end if;
    begin
        l_patient_options:=json_object_t.parse(nvl(attr(p_item,24),'{}'));
        if l_patient_options is null then raise_application_error(-20071,'Options must be an object.');end if;
    exception when others then
        p_result.message:='Display & Prefill Options must be a valid JSON object. Leave {} for defaults.';return;
    end;
    begin
        l_patient:=item_patient_data(p_item);
    exception when others then
        apex_debug.error('Clinical Anatomy 3D patient source validation %s: %s',p_item.name,sqlerrm);
        -- Findings with no patient snapshot or prefill claims can survive a source outage.
        if attr(p_item,31) is not null or l_patient_options is null or nvl(l_patient_options.get_boolean('patientDataRequired'),false)
           or json_exists(l_value,'$.context') or json_exists(l_value,'$.exam.answers.*.prefill') then
            p_result.message:='The patient source could not be verified. Retry before saving patient data or prefilled values.';return;
        end if;
    end;
    l_expected_sex:=sex(p_item,l_patient);
    l_clinic_error:=validate_payload(l_value,specialty(p_item),l_expected_sex);
    if l_clinic_error is not null then p_result.message:=l_clinic_error;return;end if;
    if nvl(attr(p_item,16),'OFF')<>'OFF' or json_exists(l_value,'$.exam') then
        execute immediate 'begin :definition:=ca3d_clinic_api.exam_definition; end;' using out l_definition;
    end if;
    l_clinic_error:=validate_patient(l_value,l_patient,attr(p_item,24),l_definition);
    if l_clinic_error is not null then p_result.message:=l_clinic_error;return;end if;
    if l_value is null then
        return;
    end if;
    begin
        l_doc   := sys.json_object_t.parse(l_value);
        l_sites := l_doc.get_array('sites');
    exception
        when others then
            l_sites := null;
    end;
    if l_sites is null then
        p_result.message := p_item.plain_label || ': the marked areas could not be read. Please mark them again.';
    elsif l_max > 0 and l_sites.get_size > l_max then
        p_result.message := p_item.plain_label || ': no more than ' || l_max || ' areas can be marked.';
    end if;
end validation;

end skeleton3d_pkg;
/
